use crate::openapi::{Context, enum_variant_name, escape, properties, rust_field};
use serde_json::{Map, Value, json};
use std::collections::BTreeSet;
use std::fmt::Write as _;

pub fn payload_constructor_tests(context: &Context<'_>) -> Result<String, String> {
    let mut output = String::from(
        "//! One test per payload constructor: `new` sets exactly the required\n//! fields, and only they are sent.\n//!\n//! This file is generated by `cargo xtask update-openapi`.\n\nuse super::assert_sends_exactly;\nuse rentman_client::model;\n\n",
    );
    for (name, schema) in context.schemas {
        let required = context.effective_required(name, schema);
        if !name.ends_with("Request") || required.is_empty() {
            continue;
        }
        let values = properties(schema)
            .iter()
            .filter(|(field, _)| required.contains(*field))
            .map(|(field, field_schema)| {
                sample_value(
                    context,
                    &context.field_type(name, field, &required),
                    name,
                    field,
                    field_schema,
                    "rentman_client::",
                )
            })
            .collect::<Result<Vec<_>, String>>()?;
        let sent = properties(schema)
            .keys()
            .filter(|field| required.contains(*field))
            .map(|field| format!("\"{}\"", escape(field)))
            .collect::<Vec<_>>();
        writeln!(output, "#[test]\nfn {}() {{\n    let payload = model::{}::new({});\n    assert_sends_exactly(&payload, \"{}\", &[{}]);\n}}\n",
            rust_field(context.type_name(name)), context.type_name(name), values.join(", "), name, sent.join(", ")).unwrap();
    }
    Ok(output)
}

pub fn response_enum_tests(context: &Context<'_>) -> String {
    let mut enums = Vec::new();
    for (name, schema) in context.schemas {
        if !name.ends_with("Response") {
            continue;
        }
        for (field, field_schema) in properties(schema) {
            if field_schema.get("enum").is_some() {
                enums.push((name.as_str(), field.as_str()));
            }
        }
    }
    let mut output = String::from(
        "//! One contract test per open response enum: every value the OpenAPI\n//! document lists must deserialize to a named variant, not to `Unknown`.\n//!\n//! This file is generated by `cargo xtask update-openapi`.\n\nuse super::assert_documented_values_are_named;\nuse rentman_client::model;\n\n/// Response schema fields that have a generated open enum.\npub(crate) const RESPONSE_ENUM_FIELDS: &[(&str, &str)] = &[\n",
    );
    for (schema, field) in &enums {
        writeln!(
            output,
            "    (\"{}\", \"{}\"),",
            escape(schema),
            escape(field)
        )
        .unwrap();
    }
    output.push_str("];\n\n");
    for (schema, field) in enums {
        let enum_name = context.enum_type_name(schema, field);
        writeln!(output, "#[test]\nfn {}() {{\n    assert_documented_values_are_named::<model::{enum_name}>(\n        \"{schema}\",\n        \"{field}\",\n        |value| matches!(value, model::{enum_name}::Unknown(_)),\n    );\n}}\n", rust_field(&format!("{schema}_{field}")).trim_end_matches('_')).unwrap();
    }
    output
}

pub fn revision_tests(context: &Context<'_>) -> Result<String, String> {
    let revision_field = context.config.revision_field.as_str();
    let mut resources = Vec::new();
    for (name, schema) in context.schemas {
        if !context.is_resource_schema(name) {
            continue;
        }
        if properties(schema).contains_key(revision_field) {
            return Err(format!(
                "{name} now documents {revision_field}; review revision support"
            ));
        }
        resources.push((context.type_name(name), name, schema));
    }
    resources.sort_by(|left, right| left.0.cmp(right.0));
    let mut output = String::from(
        "//! One contract test per resource model for Rentman's undocumented `updateHash`.\n//!\n//! This file is generated by `cargo xtask update-openapi`.\n\nuse super::assert_carries_revision;\nuse rentman_client::{model, projection_fields};\n\npub(crate) const RESOURCES_WITH_REVISION: &[&str] = &[\n",
    );
    for (resource, _, _) in &resources {
        writeln!(output, "    \"{resource}\",").unwrap();
    }
    output.push_str("];\n\n");
    for (resource, schema_name, schema) in resources {
        let required = context.effective_required(schema_name, schema);
        let mut item = Map::new();
        for (field, field_schema) in properties(schema) {
            if field == "custom" {
                item.insert(field.clone(), json!({}));
                continue;
            }
            let ty = context.field_type(schema_name, field, &required);
            item.insert(
                field.clone(),
                sample_wire(context, &ty, schema_name, field, field_schema)?,
            );
        }
        let wire = Value::Object(item).to_string();
        writeln!(output, "#[test]\nfn {}() {{\n    assert_carries_revision::<model::{resource}, projection_fields::{resource}::revision>(\n        r#\"{wire}\"#,\n        {},\n    );\n}}\n",
            rust_field(resource), properties(schema).contains_key("custom")).unwrap();
    }
    Ok(output)
}

pub fn sample_value(
    context: &Context<'_>,
    rust_type: &str,
    schema_name: &str,
    field: &str,
    schema: &Value,
    prefix: &str,
) -> Result<String, String> {
    if rust_type.starts_with("Option<") {
        return Ok("None".to_owned());
    }
    if rust_type.starts_with("Id<") {
        return Ok(format!("{prefix}Id::new(1)"));
    }
    if let Some(values) = schema.get("enum").and_then(Value::as_array) {
        let mut used = BTreeSet::new();
        if schema_name.ends_with("Response") {
            used.insert("Unknown".to_owned());
        }
        let variant = enum_variant_name(
            values
                .first()
                .ok_or_else(|| format!("empty enum at {schema_name}.{field}"))?,
            &mut used,
        );
        let module_prefix = if prefix == "rentman_client::" {
            "rentman_client::model::"
        } else {
            "crate::model::"
        };
        return Ok(format!(
            "{module_prefix}{}::{variant}",
            context.enum_type_name(schema_name, field)
        ));
    }
    let expression = match rust_type {
        "String" => "String::from(\"x\")".to_owned(),
        "DateTime<FixedOffset>" => {
            "chrono::DateTime::parse_from_rfc3339(\"2026-01-01T00:00:00+00:00\").unwrap()"
                .to_owned()
        }
        "NaiveDate" => "chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap()".to_owned(),
        "i64" => "1".to_owned(),
        "bool" => "true".to_owned(),
        "Decimal" => format!("{prefix}Decimal::ONE"),
        "ItemId" => format!("{prefix}ItemId::new(1)"),
        _ => {
            return Err(format!(
                "no sample value for {schema_name}.{field}: {rust_type}"
            ));
        }
    };
    Ok(expression)
}

pub(crate) fn sample_wire(
    context: &Context<'_>,
    rust_type: &str,
    schema_name: &str,
    field: &str,
    schema: &Value,
) -> Result<Value, String> {
    if rust_type.starts_with("Option<") {
        return Ok(Value::Null);
    }
    if rust_type.starts_with("Id<") {
        if field == "id" {
            return Ok(json!(1));
        }
        let target = rust_type
            .strip_prefix("Id<")
            .and_then(|ty| ty.strip_suffix('>'))
            .ok_or("malformed resource ID type")?;
        let collection = context
            .resources
            .iter()
            .find(|(_, resource)| resource == &target)
            .map(|(collection, _)| collection)
            .ok_or_else(|| format!("no collection found for link type {target}"))?;
        return Ok(json!(format!("/{collection}/1")));
    }
    if schema
        .get("enum")
        .and_then(Value::as_array)
        .is_some_and(|values| !values.is_empty())
    {
        return Ok(json!(
            schema["enum"][0]
                .as_str()
                .map_or_else(|| schema["enum"][0].to_string(), str::to_owned)
        ));
    }
    match rust_type {
        "String" => Ok(json!("x")),
        "DateTime<FixedOffset>" => Ok(json!("2026-01-01T00:00:00+00:00")),
        "NaiveDate" => Ok(json!("2026-01-01")),
        "i64" | "ItemId" | "Decimal" => Ok(json!(1)),
        "bool" => Ok(json!(true)),
        "EmailAddress" => Ok(json!("crew@example.test")),
        "Url" => Ok(json!("https://example.test/")),
        "CustomFields" => Ok(json!({})),
        _ => Err(format!(
            "no sample wire value for {schema_name}.{field}: {rust_type}"
        )),
    }
}

#[cfg(test)]
// Coverage is disabled for test code so the production 100% gate measures only
// generator behavior.
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::*;
    use crate::openapi::FieldOverride;
    use crate::test_support::{config_with, spec};

    fn context_for<'a>(
        spec: &'a Value,
        edit: impl FnOnce(&mut crate::openapi::GeneratorConfig),
    ) -> Context<'a> {
        Context::with_config(spec, config_with(edit)).unwrap()
    }

    fn core_field_override(rust_type: &str) -> impl FnOnce(&mut crate::openapi::GeneratorConfig) {
        let rust_type = rust_type.to_owned();
        move |config| {
            config.response_type_overrides.push(FieldOverride {
                schema: "PartResponse".to_owned(),
                field: "name".to_owned(),
                rust_type,
            });
        }
    }

    #[test]
    fn renders_tests_for_payloads_enums_and_revisions() {
        let spec = spec();
        let context = context_for(&spec, |_| {});
        let payloads = payload_constructor_tests(&context).unwrap();
        assert!(payloads.contains("fn widget_payload() {\n    let payload = model::WidgetPayload::new(String::from(\"x\"), rentman_client::model::WidgetPayloadStatus::Active, rentman_client::Decimal::ONE, true, chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(), chrono::DateTime::parse_from_rfc3339(\"2026-01-01T00:00:00+00:00\").unwrap(), rentman_client::Id::new(1), 1);"));
        assert!(!payloads.contains("WidgetUpdatePayload"));
        let enums = response_enum_tests(&context);
        assert!(enums.contains("(\"WidgetResponse\", \"status\"),"));
        assert!(enums.contains("fn widget_response_status() {\n    assert_documented_values_are_named::<model::WidgetStatus>("));
        let revisions = revision_tests(&context).unwrap();
        assert!(revisions.contains("    \"Part\",\n    \"Widget\",\n"));
        assert!(revisions.contains("r#\"{\"id\":1,\"name\":\"x\"}\"#,\n        false,"));
        assert!(revisions.contains("\"custom\":{}"));
    }

    #[test]
    fn revision_tests_support_decimal_core_fields() {
        let spec = spec();
        let context = context_for(&spec, core_field_override("Decimal"));
        let revisions = revision_tests(&context).unwrap();
        assert!(revisions.contains("r#\"{\"id\":1,\"name\":1}\"#"));
    }

    #[test]
    fn revision_tests_need_a_wire_sample_for_every_core_field() {
        let spec = spec();
        let context = context_for(&spec, core_field_override("Uuid"));
        assert_eq!(
            revision_tests(&context),
            Err("no sample wire value for PartResponse.name: Uuid".to_owned())
        );
    }

    #[test]
    fn sample_values_cover_every_payload_type() {
        let spec = spec();
        let context = context_for(&spec, |_| {});
        let none = serde_json::json!({});
        let sample = |rust_type: &str, prefix: &str| {
            sample_value(&context, rust_type, "WidgetRequest", "field", &none, prefix)
        };
        assert_eq!(sample("Option<String>", "crate::"), Ok("None".to_owned()));
        assert_eq!(
            sample("Id<Part>", "crate::"),
            Ok("crate::Id::new(1)".to_owned())
        );
        assert_eq!(
            sample("String", "crate::"),
            Ok("String::from(\"x\")".to_owned())
        );
        assert_eq!(sample("i64", "crate::"), Ok("1".to_owned()));
        assert_eq!(sample("bool", "crate::"), Ok("true".to_owned()));
        assert_eq!(
            sample("Decimal", "crate::"),
            Ok("crate::Decimal::ONE".to_owned())
        );
        assert_eq!(
            sample("ItemId", "crate::"),
            Ok("crate::ItemId::new(1)".to_owned())
        );
        assert!(
            sample("NaiveDate", "crate::")
                .unwrap()
                .starts_with("chrono::NaiveDate")
        );
        assert!(
            sample("DateTime<FixedOffset>", "crate::")
                .unwrap()
                .starts_with("chrono::DateTime")
        );
        assert_eq!(
            sample("Url", "crate::"),
            Err("no sample value for WidgetRequest.field: Url".to_owned())
        );

        let status = &spec["components"]["schemas"]["WidgetResponse"]["properties"]["status"];
        assert_eq!(
            sample_value(
                &context,
                "WidgetStatus",
                "WidgetResponse",
                "status",
                status,
                "crate::"
            ),
            Ok("crate::model::WidgetStatus::Active".to_owned())
        );
        let unknown = serde_json::json!({"enum": ["unknown"]});
        assert_eq!(
            sample_value(
                &context,
                "WidgetStatus",
                "WidgetResponse",
                "status",
                &unknown,
                "rentman_client::"
            ),
            Ok("rentman_client::model::WidgetStatus::Unknown2".to_owned())
        );
        assert_eq!(
            sample_value(
                &context,
                "WidgetPayloadStatus",
                "WidgetRequest",
                "status",
                &unknown,
                "crate::"
            ),
            Ok("crate::model::WidgetPayloadStatus::Unknown".to_owned())
        );
        assert_eq!(
            sample_value(
                &context,
                "X",
                "WidgetRequest",
                "status",
                &serde_json::json!({"enum": []}),
                "crate::"
            ),
            Err("empty enum at WidgetRequest.status".to_owned())
        );
    }

    #[test]
    fn wire_samples_cover_every_response_type() {
        let spec = spec();
        let context = context_for(&spec, |_| {});
        let none = serde_json::json!({});
        let wire = |rust_type: &str, field: &str| {
            sample_wire(&context, rust_type, "WidgetResponse", field, &none)
        };
        assert_eq!(wire("Option<String>", "name"), Ok(Value::Null));
        assert_eq!(wire("Id<Widget>", "id"), Ok(serde_json::json!(1)));
        assert_eq!(wire("Id<Part>", "part"), Ok(serde_json::json!("/parts/1")));
        assert_eq!(
            wire("Id<Part", "part"),
            Err("malformed resource ID type".to_owned())
        );
        assert_eq!(
            wire("Id<Ghost>", "part"),
            Err("no collection found for link type Ghost".to_owned())
        );
        for (rust_type, expected) in [
            ("String", serde_json::json!("x")),
            (
                "DateTime<FixedOffset>",
                serde_json::json!("2026-01-01T00:00:00+00:00"),
            ),
            ("NaiveDate", serde_json::json!("2026-01-01")),
            ("i64", serde_json::json!(1)),
            ("ItemId", serde_json::json!(1)),
            ("Decimal", serde_json::json!(1)),
            ("bool", serde_json::json!(true)),
            ("EmailAddress", serde_json::json!("crew@example.test")),
            ("Url", serde_json::json!("https://example.test/")),
            ("CustomFields", serde_json::json!({})),
        ] {
            assert_eq!(wire(rust_type, "field"), Ok(expected), "{rust_type}");
        }
        let enum_wire = |values: Value| {
            sample_wire(
                &context,
                "WidgetStatus",
                "WidgetResponse",
                "status",
                &serde_json::json!({"enum": values}),
            )
        };
        assert_eq!(
            enum_wire(serde_json::json!(["active"])),
            Ok(serde_json::json!("active"))
        );
        assert_eq!(
            enum_wire(serde_json::json!([2])),
            Ok(serde_json::json!("2"))
        );
        assert_eq!(
            enum_wire(serde_json::json!([])),
            Err("no sample wire value for WidgetResponse.status: WidgetStatus".to_owned())
        );
    }
}
